-- =====================================================================
--  Clínica veterinaria Carlitos & Snoopy — versión PostgreSQL (Supabase)
--  Mismo esquema que www/sql/backup.sql (MySQL), traducido a PostgreSQL.
--
--  Diferencias con MySQL:
--    - AUTO_INCREMENT        -> GENERATED BY DEFAULT AS IDENTITY
--    - TINYINT(1) (booleano) -> SMALLINT con CHECK (valor IN (0, 1))
--    - TINYINT UNSIGNED      -> SMALLINT con CHECK (>= 0)
--    - DECIMAL / DATETIME    -> NUMERIC / TIMESTAMP
--    - Se activa RLS en todas las tablas para que no queden abiertas
--      a la API pública de Supabase.
-- =====================================================================

-- =====================================================================
--  TABLAS AUXILIARES
-- =====================================================================

CREATE TABLE tipos_socio (
  id              INTEGER       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre          VARCHAR(40)   NOT NULL UNIQUE,
  descripcion     VARCHAR(255),
  cuota_mensual   NUMERIC(6,2)  NOT NULL DEFAULT 0 CHECK (cuota_mensual >= 0),
  descuento_pct   NUMERIC(5,2)  NOT NULL DEFAULT 0 CHECK (descuento_pct BETWEEN 0 AND 100),
  activo          SMALLINT      NOT NULL DEFAULT 1 CHECK (activo IN (0, 1)),
  fecha_creacion  DATE          NOT NULL,
  imagen          VARCHAR(255)
);

CREATE TABLE especies (
  id                    INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre                VARCHAR(40)  NOT NULL UNIQUE,
  esperanza_vida_anios  SMALLINT     NOT NULL CHECK (esperanza_vida_anios >= 0),
  es_exotica            SMALLINT     NOT NULL DEFAULT 0 CHECK (es_exotica IN (0, 1)),
  fecha_alta            DATE         NOT NULL,
  imagen                VARCHAR(255)
);

CREATE TABLE especialidades (
  id                  INTEGER       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre              VARCHAR(60)   NOT NULL UNIQUE,
  descripcion         VARCHAR(255),
  recargo_consulta    NUMERIC(6,2)  NOT NULL DEFAULT 0 CHECK (recargo_consulta >= 0),
  requiere_quirofano  SMALLINT      NOT NULL DEFAULT 0 CHECK (requiere_quirofano IN (0, 1)),
  fecha_alta          DATE          NOT NULL,
  imagen              VARCHAR(255)
);

CREATE TABLE servicios (
  id              INTEGER       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre          VARCHAR(80)   NOT NULL UNIQUE,
  descripcion     VARCHAR(255),
  precio_base     NUMERIC(7,2)  NOT NULL CHECK (precio_base >= 0),
  duracion_min    SMALLINT      NOT NULL CHECK (duracion_min >= 0),
  requiere_ayuno  SMALLINT      NOT NULL DEFAULT 0 CHECK (requiere_ayuno IN (0, 1)),
  fecha_alta      DATE          NOT NULL,
  imagen          VARCHAR(255)
);

-- =====================================================================
--  TABLAS PRINCIPALES
-- =====================================================================

CREATE TABLE propietarios (
  id                 INTEGER       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre             VARCHAR(50)   NOT NULL,
  apellidos          VARCHAR(100)  NOT NULL,
  dni                CHAR(9)       NOT NULL UNIQUE,
  telefono           VARCHAR(15)   NOT NULL,
  email              VARCHAR(100)  UNIQUE,
  direccion          VARCHAR(150),
  saldo_pendiente    NUMERIC(8,2)  NOT NULL DEFAULT 0,
  acepta_publicidad  SMALLINT      NOT NULL DEFAULT 0 CHECK (acepta_publicidad IN (0, 1)),
  fecha_alta         DATE          NOT NULL,
  foto               VARCHAR(255),
  tipo_socio_id      INTEGER       REFERENCES tipos_socio (id)
                                   ON UPDATE CASCADE ON DELETE SET NULL  -- NULL = no es socio
);

CREATE TABLE veterinarios (
  id                  INTEGER       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre              VARCHAR(50)   NOT NULL,
  apellidos           VARCHAR(100)  NOT NULL,
  num_colegiado       VARCHAR(20)   NOT NULL UNIQUE,
  telefono            VARCHAR(15),
  email               VARCHAR(100),
  anios_experiencia   SMALLINT      NOT NULL DEFAULT 0 CHECK (anios_experiencia >= 0),
  hace_urgencias      SMALLINT      NOT NULL DEFAULT 0 CHECK (hace_urgencias IN (0, 1)),
  fecha_contratacion  DATE          NOT NULL,
  foto                VARCHAR(255),
  especialidad_id     INTEGER       NOT NULL REFERENCES especialidades (id)
                                    ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE mascotas (
  id                INTEGER       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre            VARCHAR(50)   NOT NULL,
  raza              VARCHAR(50),
  num_chip          VARCHAR(15)   UNIQUE,
  peso_kg           NUMERIC(6,2)  NOT NULL CHECK (peso_kg > 0),
  vacunada          SMALLINT      NOT NULL DEFAULT 0 CHECK (vacunada IN (0, 1)),
  esterilizada      SMALLINT      NOT NULL DEFAULT 0 CHECK (esterilizada IN (0, 1)),
  fecha_nacimiento  DATE          NOT NULL,
  foto              VARCHAR(255),
  especie_id        INTEGER       NOT NULL REFERENCES especies (id)
                                  ON UPDATE CASCADE ON DELETE RESTRICT,
  propietario_id    INTEGER       NOT NULL REFERENCES propietarios (id)
                                  ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE citas (
  id              INTEGER       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fecha_hora      TIMESTAMP     NOT NULL,
  motivo          VARCHAR(150)  NOT NULL,
  observaciones   TEXT,
  precio_final    NUMERIC(7,2)  NOT NULL DEFAULT 0 CHECK (precio_final >= 0),
  atendida        SMALLINT      NOT NULL DEFAULT 0 CHECK (atendida IN (0, 1)),
  imagen          VARCHAR(255),
  mascota_id      INTEGER       NOT NULL REFERENCES mascotas (id)
                                ON UPDATE CASCADE ON DELETE RESTRICT,
  veterinario_id  INTEGER       NOT NULL REFERENCES veterinarios (id)
                                ON UPDATE CASCADE ON DELETE RESTRICT,
  servicio_id     INTEGER       NOT NULL REFERENCES servicios (id)
                                ON UPDATE CASCADE ON DELETE RESTRICT
);

-- Índices de las claves foráneas (PostgreSQL no los crea solo, MySQL sí)
CREATE INDEX idx_propietarios_tipo_socio   ON propietarios (tipo_socio_id);
CREATE INDEX idx_veterinarios_especialidad ON veterinarios (especialidad_id);
CREATE INDEX idx_mascotas_especie          ON mascotas (especie_id);
CREATE INDEX idx_mascotas_propietario      ON mascotas (propietario_id);
CREATE INDEX idx_citas_fecha               ON citas (fecha_hora);
CREATE INDEX idx_citas_mascota             ON citas (mascota_id);
CREATE INDEX idx_citas_veterinario         ON citas (veterinario_id);
CREATE INDEX idx_citas_servicio            ON citas (servicio_id);

-- Sin políticas: la API pública (anon) no puede leer ni escribir.
-- La aplicación conecta directamente a la base de datos y no le afecta.
ALTER TABLE tipos_socio    ENABLE ROW LEVEL SECURITY;
ALTER TABLE especies       ENABLE ROW LEVEL SECURITY;
ALTER TABLE especialidades ENABLE ROW LEVEL SECURITY;
ALTER TABLE servicios      ENABLE ROW LEVEL SECURITY;
ALTER TABLE propietarios   ENABLE ROW LEVEL SECURITY;
ALTER TABLE veterinarios   ENABLE ROW LEVEL SECURITY;
ALTER TABLE mascotas       ENABLE ROW LEVEL SECURITY;
ALTER TABLE citas          ENABLE ROW LEVEL SECURITY;

